package com.projecthero.mod.quirk.fx;

import com.projecthero.mod.ProjectHeroMod;

import net.fabricmc.fabric.api.particle.v1.FabricParticleTypes;

import net.minecraft.core.Registry;
import net.minecraft.core.particles.SimpleParticleType;
import net.minecraft.core.registries.BuiltInRegistries;

/**
 * v0.17.1 Quirk framework: the shared Quirk particles (client factories in {@code client.quirk.fx.QuirkParticleClient},
 * sprites generated by {@code scratchpad/gen_quirk_framework_textures.js}). Use these instead of vanilla flame / smoke /
 * crit, which read as cheap next to the code-drawn effects:
 * <ul>
 * <li>{@link #EMBER} -- a full-bright orange-white ember that rises, flickers and cools to red;</li>
 * <li>{@link #SPARK} -- a full-bright streak that flies fast, falls a little and dies (palm crackle, kick impacts);</li>
 * <li>{@link #SMOKE_PUFF} -- a soft lit grey puff that swells and drifts up (blast crowns, exhaust);</li>
 * <li>{@link #SHADOW_MOTE} -- a dark violet-black mote that drifts and fades (Dark Shadow);</li>
 * <li>{@link #STEAM} -- a pale wisp that rises fast and spreads (Heat Vent, cooling);</li>
 * <li>{@link #PINK_SPARKLE} -- a full-bright pink twinkle (Zero Gravity touch marks);</li>
 * <li>{@link #DUST_CHUNK} -- a falling grit chunk that bounces (Overhaul, landings).</li>
 * </ul>
 * The velocity arguments of {@code sendParticles} with count 0 are the particle's velocity, as vanilla.
 */
public final class QuirkParticles {
	public static final SimpleParticleType EMBER = FabricParticleTypes.simple(true);
	public static final SimpleParticleType SPARK = FabricParticleTypes.simple(true);
	public static final SimpleParticleType SMOKE_PUFF = FabricParticleTypes.simple(false);
	public static final SimpleParticleType SHADOW_MOTE = FabricParticleTypes.simple(false);
	public static final SimpleParticleType STEAM = FabricParticleTypes.simple(false);
	public static final SimpleParticleType PINK_SPARKLE = FabricParticleTypes.simple(true);
	public static final SimpleParticleType DUST_CHUNK = FabricParticleTypes.simple(false);

	private static boolean registered;

	private QuirkParticles() {
	}

	public static void register() {
		if (registered) {
			return;
		}
		registered = true;
		Registry.register(BuiltInRegistries.PARTICLE_TYPE, ProjectHeroMod.id("quirk_ember"), EMBER);
		Registry.register(BuiltInRegistries.PARTICLE_TYPE, ProjectHeroMod.id("quirk_spark"), SPARK);
		Registry.register(BuiltInRegistries.PARTICLE_TYPE, ProjectHeroMod.id("quirk_smoke_puff"), SMOKE_PUFF);
		Registry.register(BuiltInRegistries.PARTICLE_TYPE, ProjectHeroMod.id("quirk_shadow_mote"), SHADOW_MOTE);
		Registry.register(BuiltInRegistries.PARTICLE_TYPE, ProjectHeroMod.id("quirk_steam"), STEAM);
		Registry.register(BuiltInRegistries.PARTICLE_TYPE, ProjectHeroMod.id("quirk_pink_sparkle"), PINK_SPARKLE);
		Registry.register(BuiltInRegistries.PARTICLE_TYPE, ProjectHeroMod.id("quirk_dust_chunk"), DUST_CHUNK);
	}
}
